# Generates the two repository-only projections: ai-map.json (the machine-readable cold-start map
# for AI agents) and repository-index.md (the human file index of the canonical documents).
# AUTO-GENERATED artifacts (GOVERNANCE.md class 3): never hand-edit either; run this.
# SSOT-safe: every value is either a POINTER (path) or a field EXTRACTED from its SSOT at
# generation time (with a `source`), never an authored restatement. Regenerating fixes drift.
#
# DETERMINISTIC, so a projection can be VERIFIED by reproducing it (SPEC-270). The same inputs give
# the same bytes on every run and every machine: LF line endings (OPS-4: `ConvertTo-Json` emits the
# platform newline, so every Windows regeneration carried 262 CR bytes that were converted by hand),
# and no generation timestamp (git records when a file changed; a timestamp made every run a diff).
# `-Check` writes nothing: it regenerates both projections in memory and exits 1 naming each file
# whose LF-normalized bytes differ. Check 7 of scripts/check_repository_consistency.ps1 runs it, so a
# stale projection fails every guard run, CI included, instead of waiting to be noticed
# (repository-index.md went stale on 2026-08-10 and nothing saw it for two months).
# Pure ASCII.
param([switch]$Check)

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot

function Get-Field($text, $label) {
    if ($text -match "(?m)^$([regex]::Escape($label))\s*(.+?)\s*$") { return $matches[1].Trim() }
    return $null
}

# Multi-line variant. "Next capability:" became an ordered multi-step block on 2026-08-17;
# Get-Field captures only its first line, which would ship a cold-start map naming the objective
# but omitting the steps that qualify it (verify-tools-first, read the mandatory corrections,
# read the built artifact back). Captures through to the next documented manifest label or
# markdown structure. TERMINATOR SET IS DUPLICATED, DELIBERATELY, in
# scripts/check_repository_consistency.ps1 Check 7, which compares this exact value -- change
# both together; they are cross-referenced in each other's comments.
function Get-Block($text, $label) {
    $terminators = '---|#\s|Prior phases\b|Current Phase:|Current Module:|Active Change Request:|Last Completed:|Context & remaining'
    $pattern = "(?ms)^" + [regex]::Escape($label) + "\s*(?<v>.*?)(?=\r?\n(?:$terminators)|\z)"
    $m = [regex]::Match($text, $pattern)
    if ($m.Success) { return $m.Groups['v'].Value.Trim() }
    return $null
}

# Read as UTF-8 explicitly: under Windows PowerShell 5.1 the default read codepage is ANSI,
# which corrupts em-dashes/Unicode in the manifest into mojibake (e.g. "â€”").
$manifestPath = "_ORVION_CANONICAL/manifest.md"
$manifest = Get-Content (Join-Path $root $manifestPath) -Raw -Encoding utf8

# Ordinal order, so the listing does not depend on the machine's culture.
$docs = @(Get-ChildItem -Path (Join-Path $root "_ORVION_CANONICAL") -Filter "*.md" | Sort-Object Name -Culture ([cultureinfo]::InvariantCulture))
$canonical = @()
$indexLines = @(
    "# Repository Index",
    "",
    "Generated by scripts/generate-ai-map.ps1 -- do not hand-edit.",
    "",
    "| Path | Version | Status | Canonical | Layer |",
    "| --- | --- | --- | --- | --- |"
)
foreach ($f in $docs) {
    $c = Get-Content $f.FullName -Raw -Encoding utf8
    $num = if ($f.Name -match '^(\d\d)_') { [int]$matches[1] } else { -1 }
    $layer = if ($num -ge 0 -and $num -le 23) { "business/domain" }
             elseif ($num -ge 24 -and $num -le 33) { "schema/database" }
             else { "governance/operational" }
    $version = if ($c -match 'Version:\s*(\S+)') { $matches[1] } else { $null }
    $status  = if ($c -match 'Status:\s*(.+)')  { $matches[1].Trim() } else { $null }
    $canon   = if ($c -match 'Canonical:\s*(\S+)') { $matches[1] } else { $null }
    $canonical += [ordered]@{
        path    = "_ORVION_CANONICAL/$($f.Name)"
        version = $version
        status  = $status
        layer   = $layer
    }
    $indexLines += "| _ORVION_CANONICAL/$($f.Name) | $(if ($version) { $version } else { '-' }) | $(if ($status) { $status } else { '-' }) | $(if ($canon) { $canon } else { '-' }) | $layer |"
}

$map = [ordered]@{
    "_comment"   = "AUTO-GENERATED by scripts/generate-ai-map.ps1 -- do not hand-edit. Machine-readable cold-start map for AI agents. Every value is a pointer or is extracted from its SSOT; the authority is the cited file, never this map. Regenerate to refresh."
    project      = "ORVION"
    one_liner    = "Travel CRM / operations / revenue platform for Egyptian travel agencies; Supabase/PostgreSQL backend = SQL migrations + app-schema RPCs. No application UI yet."
    boot_order   = @("README.md","pwsh -NoProfile -File scripts/check_agent_continuity.ps1 -Boot","(follow Boot ACTION and START_CONTEXT pointers)")
    live_state   = [ordered]@{
        source                = $manifestPath
        phase                 = Get-Field $manifest "Current Phase:"
        active_change_request = Get-Field $manifest "Active Change Request:"
        last_completed        = Get-Field $manifest "Last Completed:"
        next_capability       = Get-Block $manifest "Next capability:"
    }
    authority = [ordered]@{
        execution_conduct   = "AGENTS.md"
        knowledge_ssot      = "GOVERNANCE.md (section 2 SSOT matrix)"
        cr_state_machine    = "CR_LIFECYCLE.md"
        coding_standards    = "CODING_STANDARDS.md"
        ratified_decisions  = "reports/architecture-decision-records.md"
        accepted_findings   = "reports/master/MASTER_GAP_REGISTER.md"
        deferred_and_triggers = "reports/future-backlog.md"
        schema_truth        = "supabase/migrations/**"
        live_state          = $manifestPath
        file_index          = "repository-index.md"
    }
    verify = [ordered]@{
        start = "npx supabase start"
        reset = "npx supabase db reset"
        smoke = "docker exec -i supabase_db_ORVION psql -U postgres -d postgres -f - < scripts/verify_database.sql  (expect: ALL CHECKS PASSED)"
        impact = "pwsh -NoProfile -File scripts/impact.ps1 -Target <name>  (query, not a guard: what consumes/derives from a structure -- AGENTS.md 5b question 2)"
    }
    canonical_docs = $canonical
    counts = [ordered]@{ canonical_docs = $canonical.Count }
}

$outputs = [ordered]@{
    "ai-map.json"         = ($map | ConvertTo-Json -Depth 6) -replace "`r`n", "`n"
    "repository-index.md" = ($indexLines -join "`n") + "`n"
}

if ($Check) {
    $stale = @()
    foreach ($name in $outputs.Keys) {
        $path = Join-Path $root $name
        $have = if (Test-Path -LiteralPath $path) { [IO.File]::ReadAllText($path) -replace "`r`n", "`n" } else { $null }
        if ($have -cne $outputs[$name]) { $stale += $name }
    }
    if ($stale.Count) { foreach ($s in $stale) { "GENERATED STALE: $s does not reproduce from its sources -- run pwsh -NoProfile -File scripts/generate-ai-map.ps1" }; exit 1 }
    "GENERATED: ai-map.json and repository-index.md reproduce from their sources"
    exit 0
}

# UTF-8 WITHOUT BOM, LF, edition-independently.
$utf8 = New-Object System.Text.UTF8Encoding($false)
foreach ($name in $outputs.Keys) { [IO.File]::WriteAllText((Join-Path $root $name), $outputs[$name], $utf8) }
Write-Host "ai-map.json and repository-index.md generated ($($canonical.Count) canonical docs, phase extracted from manifest)."
